(()=>{'use strict';const launch=document.querySelector('.contact-float a');if(!launch)return;launch.textContent='✦ Bilgi asistanı';launch.setAttribute('aria-haspopup','dialog');const panel=document.createElement('dialog');panel.className='info-assistant';panel.setAttribute('aria-labelledby','info-title');panel.innerHTML='<div class="info-top"><div><strong id="info-title">FuLab Bilgi Asistanı</strong><small>Hizmetler ve ilk adımlar</small></div><button type="button" class="info-close" aria-label="Asistanı kapat">×</button></div><p>Merhaba! FuLab hakkında ne öğrenmek istersiniz?</p><div class="info-questions"></div><div class="info-answer" role="status" aria-live="polite">Aşağıdaki konulardan birini seçebilirsiniz. Bu bölüm hazır bilgilendirme yanıtları sunar.</div><a class="info-next" href="/asistan.html">İhtiyacımı talep asistanına anlat →</a><a class="info-guide" href="/ai-rehber/">AI Rehber yazılarını keşfet ↗</a>';document.body.append(panel);const entries=[['AI çalışanlar ne yapar?','FuLab’ın 8 AI çalışanı; karşılama, satış, müşteri desteği, teklif, CRM, satın alma, muhasebe ve yönetim süreçlerini destekler. Görevler, bilgi kaynakları ve insan onayı adımları işletmenize göre belirlenir.'],['Hangi sistemlere bağlanır?','WhatsApp, e-posta, Telegram, CRM, ERP ve API sunan araçlar birlikte değerlendirilir. Bağlantı kapsamı kullandığınız sistemin sürümüne, erişim izinlerine ve API desteğine bağlıdır.'],['Fiyatlandırma nasıl yapılır?','Fiyat; seçilen çalışanlara, görev kapsamına, entegrasyonlara ve işlem hacmine göre belirlenir. İhtiyacınızı talep asistanıyla paylaşarak size özel bir değerlendirme isteyebilirsiniz.'],['Nasıl başlayabilirim?','Ana sayfadaki Kendi AI Ekibini Oluştur bölümünden rolleri seçin, ihtiyacınızı yazın ve planınızı inceleyin. Ardından planı WhatsApp veya e-posta ile paylaşabilirsiniz.'],['Size nasıl ulaşırım?','E-posta: fatih@fulabtr.net · WhatsApp: 0551 210 80 80 · Adres: Balıkesir Üniversitesi Teknokenti · Bandırma, Balıkesir.']];for(const [question,answer] of entries){const b=document.createElement('button');b.type='button';b.textContent=question;b.addEventListener('click',()=>{panel.querySelector('.info-answer').textContent=answer;});panel.querySelector('.info-questions').append(b);}launch.addEventListener('click',e=>{e.preventDefault();panel.showModal();});panel.querySelector('.info-close').addEventListener('click',()=>panel.close());panel.addEventListener('click',e=>{if(e.target===panel){const rect=panel.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)panel.close();}});panel.addEventListener('close',()=>launch.focus());})();
